//! The repo contract: the files a repo must carry, the commands Hulahoop runs,
//! and the environment a run is allowed to see.

use crate::{RunFlag, CONTRACT_VERSION};
use std::path::{Path, PathBuf};

/// Files the repo must ship. `.envrc` is generated by the runner when missing,
/// which is why it is not in this list.
pub const REQUIRED_FILES: [&str; 2] = ["flake.nix", "justfile"];

/// Files whose modification means the run changed the toolchain or the test
/// command itself, so a human has to acknowledge it before approving.
pub const GATED_FILES: [&str; 4] = ["flake.nix", "flake.lock", "justfile", ".envrc"];

pub const ENVRC_CONTENT: &str = "use flake\n";

/// Whole-suite recipe. There is deliberately no per-test entry point: a suite
/// that is run selectively stops being proof of anything.
pub fn test_command() -> Vec<String> {
    vec![
        "direnv".into(),
        "exec".into(),
        ".".into(),
        "just".into(),
        "test".into(),
    ]
}

pub fn setup_command() -> Vec<String> {
    vec![
        "direnv".into(),
        "exec".into(),
        ".".into(),
        "just".into(),
        "setup".into(),
    ]
}

pub fn contract_metadata_command() -> Vec<String> {
    vec![
        "nix".into(),
        "flake".into(),
        "metadata".into(),
        "--no-write-lock-file".into(),
    ]
}

/// Preflight for one adapter inside a repo's dev shell.
pub fn probe_command(adapter: crate::Adapter, model: &str) -> Vec<String> {
    use crate::Adapter;
    match adapter {
        Adapter::Pi => vec![
            "direnv".into(),
            "exec".into(),
            ".".into(),
            "pi".into(),
            "--version".into(),
        ],
        Adapter::ClaudeCode => vec![
            "direnv".into(),
            "exec".into(),
            ".".into(),
            "claude".into(),
            "--version".into(),
        ],
        // The scripted adapter has no CLI, so there is nothing to resolve through
        // a dev shell: the probe is the shell itself.
        Adapter::Fake => vec!["sh".into(), "-c".into(), format!("echo fake {model}")],
    }
}

/// Env vars a run is allowed to inherit from the runner, before the allowlist
/// the runner adds. Everything else is dropped by `env_clear`.
pub const INHERITED_ENV: [&str; 6] = ["PATH", "TMPDIR", "TERM", "LANG", "LC_ALL", "USER"];

/// Variables Hulahoop sets itself. Passed by name, never inherited wholesale.
pub const HULAHOOP_ENV: [&str; 7] = [
    "HULAHOOP_INPUT",
    "HULAHOOP_RUN_ID",
    "HULAHOOP_AGENT",
    "HULAHOOP_CHECKOUT",
    "HULAHOOP_ARTIFACT_DIR",
    "HULAHOOP_BASE_BOOKMARK",
    "HULAHOOP_PROMPT",
];

/// Adapter credentials that must survive the clean environment.
pub const CREDENTIAL_ENV: [&str; 8] = [
    "ANTHROPIC_API_KEY",
    "ANTHROPIC_AUTH_TOKEN",
    "ANTHROPIC_BASE_URL",
    "OPENAI_API_KEY",
    "OPENAI_BASE_URL",
    "PI_API_KEY",
    "PI_MODEL",
    "CLAUDE_CONFIG_DIR",
];

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PathVerdict {
    /// Implementation code, free to change.
    Allowed,
    /// A contract file: allowed, but the approval has to acknowledge it.
    Gated(RunFlag),
}

/// Classify one changed path against the contract.
pub fn classify_path(path: &str) -> PathVerdict {
    let normalized = path.trim_start_matches("./");
    if GATED_FILES.contains(&normalized) {
        return PathVerdict::Gated(RunFlag::TouchedContract);
    }
    PathVerdict::Allowed
}

/// Paths that must never enter a run diff.
pub fn is_excluded(path: &str) -> bool {
    let p = path.trim_start_matches("./");
    p == ".envrc" || p == ".hulahoop" || p.starts_with(".hulahoop/")
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PreflightError {
    MissingFiles(Vec<String>),
    FlakeFails(String),
    JustFails(String),
    VersionMismatch { found: String },
}

impl std::fmt::Display for PreflightError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            PreflightError::MissingFiles(files) => write!(
                f,
                "this repo is not a Hulahoop contract repo: missing {}. Hulahoop needs a flake.nix and a justfile with `setup` and `test` recipes (contract {}).",
                files.join(", "),
                CONTRACT_VERSION
            ),
            PreflightError::FlakeFails(msg) => write!(
                f,
                "flake.nix does not evaluate in this repo: {msg}. Run `nix flake metadata` there and fix the error before adding the repo."
            ),
            PreflightError::JustFails(msg) => write!(
                f,
                "the justfile does not expose `setup` and `test`: {msg}. Both recipes are required (contract {}).",
                CONTRACT_VERSION
            ),
            PreflightError::VersionMismatch { found } => write!(
                f,
                "this repo was last used with Hulahoop contract {found}, this build speaks {CONTRACT_VERSION}. Run the migration steps in README §7, or create a fresh checkout of the repo."
            ),
        }
    }
}

/// Cheap structural preflight, before any command runs.
pub fn check_files(root: &Path) -> Result<(), PreflightError> {
    let missing: Vec<String> = REQUIRED_FILES
        .iter()
        .filter(|name| !root.join(name).exists())
        .map(|name| (*name).to_string())
        .collect();
    if missing.is_empty() {
        Ok(())
    } else {
        Err(PreflightError::MissingFiles(missing))
    }
}

/// `direnv exec` needs an `.envrc`; the runner writes one when the repo lacks it
/// and allows it for that path. A committed `.envrc` is left alone (and gated).
pub fn needs_generated_envrc(root: &Path) -> bool {
    !root.join(".envrc").exists()
}

/// The one checkout a task works in, shared by every turn of that task:
/// `checkouts/<project>/<issue>`. Keeping it between turns keeps what the
/// project built (target/, node_modules, .venv) so a rework starts warm. It is
/// deleted when the task is merged, closed or cancelled.
pub fn checkout_dir(data_dir: &Path, project: &str, issue: &uuid::Uuid) -> PathBuf {
    data_dir
        .join("checkouts")
        .join(project)
        .join(issue.to_string())
}

/// The Hulahoop-owned clone of a repository's url that every checkout of it is
/// a workspace of.
pub fn mirror_dir(data_dir: &Path, repo_id: &uuid::Uuid) -> PathBuf {
    data_dir.join("mirrors").join(repo_id.to_string())
}

/// Whether `path` is a task checkout this data directory owns, and so one a
/// runner may rebuild or delete: exactly `checkouts/<project id>/<task id>`
/// below the data directory, every part of it a plain name, and none of the
/// parts that exist on disk a symlink that could lead somewhere else. The data
/// directory itself is compared by its canonical path, so a data directory
/// reached through a symlink still owns its checkouts.
pub fn is_owned_checkout(data_dir: &Path, path: &Path) -> bool {
    use std::path::Component;
    let canonical = data_dir
        .canonicalize()
        .unwrap_or_else(|_| data_dir.to_path_buf());
    let Some(rest) = path
        .strip_prefix(data_dir)
        .or_else(|_| path.strip_prefix(&canonical))
        .ok()
    else {
        return false;
    };
    let parts: Vec<_> = rest.components().collect();
    let [Component::Normal(checkouts), Component::Normal(project), Component::Normal(issue)] =
        parts.as_slice()
    else {
        return false;
    };
    let is_id = |part: &std::ffi::OsStr| {
        part.to_str()
            .is_some_and(|text| uuid::Uuid::parse_str(text).is_ok_and(|id| id.to_string() == text))
    };
    if *checkouts != "checkouts" || !is_id(project) || !is_id(issue) {
        return false;
    }
    let mut below = canonical;
    for part in [checkouts, project, issue] {
        below.push(part);
        match std::fs::symlink_metadata(&below) {
            Ok(meta) if meta.file_type().is_symlink() => return false,
            Ok(_) => {}
            // Not there yet: nothing below it can be a symlink either.
            Err(_) => break,
        }
    }
    true
}

pub fn run_artifact_dir(data_dir: &Path, run_id: &uuid::Uuid) -> PathBuf {
    data_dir.join("runs").join(run_id.to_string())
}

/// The empty working directory a run on a task with no repository works in.
/// Private to the run, created fresh before the agent starts and deleted after.
pub fn scratch_dir(data_dir: &Path, run_id: &uuid::Uuid) -> PathBuf {
    data_dir.join("scratch").join(run_id.to_string())
}

pub fn scratch_home(data_dir: &Path, adapter: crate::Adapter) -> PathBuf {
    data_dir.join("home").join(adapter.as_str())
}

pub fn connection_file(data_dir: &Path) -> PathBuf {
    data_dir.join("connection.json")
}

pub fn database_file(data_dir: &Path) -> PathBuf {
    data_dir.join("hulahoop.sqlite")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_task_has_one_checkout_findable_by_project_and_issue() {
        let project = uuid::Uuid::nil();
        let issue = uuid::Uuid::now_v7();
        let path = checkout_dir(Path::new("/data"), &project.to_string(), &issue);
        assert_eq!(
            path,
            Path::new("/data/checkouts")
                .join(project.to_string())
                .join(issue.to_string())
        );
    }

    #[test]
    fn only_checkouts_named_by_project_and_task_ids_are_owned() {
        let data = Path::new("/data");
        let (p, i) = (uuid::Uuid::now_v7(), uuid::Uuid::now_v7());
        let owned = checkout_dir(data, &p.to_string(), &i);
        assert!(is_owned_checkout(data, &owned));
        let checkouts = data.join("checkouts");
        for path in [
            checkouts.clone(),
            checkouts.join(p.to_string()),
            owned.join("target"),
            checkouts.join("p").join(i.to_string()),
            checkouts.join(p.to_string()).join("i"),
            checkouts
                .join(p.to_string())
                .join(i.to_string().to_uppercase()),
            data.join("mirrors").join(p.to_string()).join(i.to_string()),
            Path::new("/home/me/src/repo").to_path_buf(),
            checkouts.join(p.to_string()).join("..").join(i.to_string()),
            Path::new("/elsewhere/checkouts")
                .join(p.to_string())
                .join(i.to_string()),
        ] {
            assert!(!is_owned_checkout(data, &path), "{}", path.display());
        }
    }

    /// A symlink anywhere below the data directory could point a deletion
    /// somewhere else, so a checkout reached through one is not owned; a data
    /// directory reached through one still owns its checkouts.
    #[cfg(unix)]
    #[test]
    fn a_symlinked_checkout_is_not_owned() {
        let root = std::env::temp_dir().join(format!("hulahoop-owned-{}", uuid::Uuid::now_v7()));
        let data = root.join("data");
        let (p, i) = (uuid::Uuid::now_v7(), uuid::Uuid::now_v7());
        let checkout = checkout_dir(&data, &p.to_string(), &i);
        std::fs::create_dir_all(&checkout).unwrap();
        assert!(is_owned_checkout(&data, &checkout));

        let link = root.join("link");
        std::os::unix::fs::symlink(&data, &link).unwrap();
        assert!(is_owned_checkout(
            &link,
            &checkout_dir(&link, &p.to_string(), &i)
        ));
        assert!(is_owned_checkout(&link, &checkout));

        let elsewhere = root.join("elsewhere");
        std::fs::create_dir_all(&elsewhere).unwrap();
        let other = uuid::Uuid::now_v7();
        std::os::unix::fs::symlink(&elsewhere, data.join("checkouts").join(other.to_string()))
            .unwrap();
        assert!(!is_owned_checkout(
            &data,
            &checkout_dir(&data, &other.to_string(), &i)
        ));
        std::os::unix::fs::symlink(&elsewhere, checkout_dir(&data, &p.to_string(), &other))
            .unwrap();
        assert!(!is_owned_checkout(
            &data,
            &checkout_dir(&data, &p.to_string(), &other)
        ));
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn contract_files_are_gated() {
        assert_eq!(
            classify_path("./justfile"),
            PathVerdict::Gated(RunFlag::TouchedContract)
        );
        assert_eq!(classify_path("calc.py"), PathVerdict::Allowed);
    }

    #[test]
    fn generated_envrc_never_reaches_a_diff() {
        assert!(is_excluded(".envrc"));
        assert!(is_excluded("./.hulahoop/junit.xml"));
        assert!(!is_excluded("justfile"));
    }

    #[test]
    fn missing_contract_files_are_named() {
        let err = check_files(Path::new("/nonexistent-repo")).unwrap_err();
        assert!(matches!(err, PreflightError::MissingFiles(_)));
        let message = err.to_string();
        assert!(message.contains("flake.nix"));
        assert!(message.contains("justfile"));
    }
}
